from datetime import datetime, timedelta
from pathlib import Path
import tempfile
import unittest

import categories
import database
import importers
import models


NOW = datetime(2026, 11, 2, 10)


def record(**changes):
    """Return a valid canonical source candidate with optional test overrides."""
    values = {'source': 'uniclubs', 'external_id': 'club-1', 'title': 'Python workshop',
              'start': NOW + timedelta(days=1), 'end': NOW + timedelta(days=1, hours=2),
              'location': 'SQUARE', 'club_name': 'Tech Club', 'club_category': 'Academic',
              'price': '25.00', 'status': 'open'}
    values.update(changes)
    return values


def event(**changes):
    """Return a domain occurrence with fixed dates and optional test overrides."""
    values = {'event_id': 42, 'series_id': 1, 'title': 'Python workshop',
              'start': NOW, 'end': NOW + timedelta(hours=2), 'location': 'SQUARE',
              'location_type': 'st_gallen', 'direction_key': 'career',
              'bundle_key': 'career_tech', 'bundle_name': 'Tech & data', 'price': '25.00'}
    values.update(changes)
    return models.Event(**values)


def calendar(*events):
    """Wrap supplied VEVENT text in a complete fixed ICS calendar."""
    return '\r\n'.join(['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//WeekWise test//EN',
                        *events, 'END:VCALENDAR', ''])


def calendar_event(*lines):
    """Wrap supplied property lines in one test VEVENT."""
    return '\r\n'.join(['BEGIN:VEVENT', *lines, 'END:VEVENT'])


class DatabaseCase(unittest.TestCase):
    """Supply temporary files, a fresh in-memory schema and the frozen taxonomy."""

    def setUp(self):
        """Create isolated fixtures without touching the app's generated files."""
        self.connection = database.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        database.init_db(self.connection)
        self.taxonomy = categories.load_taxonomy()
        categories.seed_categories(self.connection, self.taxonomy)
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.directory = Path(temporary.name)
        self.paths = {'sources_dir': self.directory / 'sources',
                      'snapshot_dir': self.directory / 'snapshots',
                      'private_file': self.directory / 'private.json'}

    def scalar(self, query, params=()):
        """Return one value from fixed fixture SQL with bound parameters."""
        return self.connection.execute(query, params).fetchone()[0]

    def save(self, rows=None, **options):
        """Import a UniClubs batch with the fixed test clock."""
        return importers.save_records(self.connection, rows or [record()], 'uniclubs',
                                      self.taxonomy, now=NOW, **options)
